public final class Wallet {
    public static final long MAX_BALANCE_MINOR = 10_000_000L;

    private final String owner;
    private long balanceMinor;

    public Wallet(String owner) { this.owner = owner; }

    public static Wallet open(String owner) { return new Wallet(owner); }

    public long getBalanceMinor() { return balanceMinor; }

    public long deposit(long amountMinor) { return deposit(amountMinor, "EUR"); }
    public long deposit(long amountMinor, String currency) {
        balanceMinor += amountMinor;
        return balanceMinor;
    }
}

kotlin.src:
class Wallet(val owner: String) {
    var balanceMinor: Long = 0
        private set

    @JvmOverloads
    fun deposit(amountMinor: Long, currency: String = "EUR"): Long {
        balanceMinor += amountMinor
        return balanceMinor
    }

    companion object {
        const val MAX_BALANCE_MINOR = 10_000_000L
        @JvmStatic fun open(owner: String) = Wallet(owner)
    }
}

